def max_lift_to_drag(cd0, e, aspect_ratio):
    """Return the maximum lift-to-drag ratio (L/D)max for a parabolic drag polar
    CD = CD0 + k*CL^2 with k = 1/(pi * e * AR); e is the Oswald efficiency factor.
    Assumes cd0 > 0, 0 < e <= 1, aspect_ratio > 0, and that the quadratic polar holds."""
    k = 1.0 / (math.pi * e * aspect_ratio)
    return 1.0 / (2.0 * math.sqrt(cd0 * k))

def tsiolkovsky_dv(isp_s, m0, mf):
    """Return ideal rocket delta-v in m/s from specific impulse isp_s in SECONDS, initial mass m0
    and final mass mf (same units). Use g0 = 9.80665 m/s^2 and the NATURAL logarithm.
    Assumes m0 >= mf > 0 and constant exhaust velocity; no gravity or drag losses."""
    return isp_s * 9.80665 * math.log(m0 / mf)

def solve_kepler(M, e):
    """Return the eccentric anomaly E in RADIANS solving Kepler's equation M = E - e*sin(E) for
    mean anomaly M in radians (any real value) and eccentricity 0 <= e < 1. Iterate (e.g. Newton)
    until the change is below 1e-12, and raise RuntimeError if it does not converge in 50 iterations."""
    if not 0 <= e < 1:
        raise ValueError("elliptic orbits only")
    Mr = math.remainder(M, 2 * math.pi)          # principal value in [-pi, pi]; whole revolutions restored below
    E = Mr if e < 0.8 else math.copysign(math.pi, Mr)
    for _ in range(50):
        dE = (E - e * math.sin(E) - Mr) / (1 - e * math.cos(E))
        E -= dE
        if abs(dE) < 1e-12:
            return E + (M - Mr)
    raise RuntimeError("Kepler solver did not converge")

def quat_rotate(q_wxyz, v):
    """Actively rotate 3-vector v by the unit quaternion q given SCALAR-FIRST as [w, x, y, z]
    (Hamilton convention, right-handed frame). Return the rotated vector as a list of 3 floats.
    Assumes q has unit norm."""
    w, x, y, z = q_wxyz
    return Rotation.from_quat([x, y, z, w]).apply(v).tolist()

