problems.canonical_solution:
def stall_speed(mass_kg, rho, S, CLmax):
    """Return stall speed in m/s. mass_kg is aircraft MASS in kg (weight = mass * 9.80665 N);
    rho is air density in kg/m^3; S is wing area in m^2; CLmax is the maximum lift coefficient
    for the configuration. Assumes steady level flight (lift = weight) and positive inputs."""
    return math.sqrt(2 * mass_kg * 9.80665 / (rho * S * CLmax))

def cantilever_tip_deflection(P, L, E, b, h):
    """Return tip deflection in m of a rectangular cantilever with tip load P [N], length L [m],
    Young's modulus E [Pa], width b [m] and depth h [m] in the direction of the load
    (second moment of area I = b*h^3/12). Assumes a prismatic, linear-elastic beam with small
    deflections (Euler-Bernoulli)."""
    return P * L ** 3 / (3 * E * (b * h ** 3 / 12))
